<?php
session_start();
require_once 'includes/config.php';

if (isset($_SESSION['user_id'])) {
    if ($_SESSION['user_role'] == 'admin') { header("Location: admin/dashboard.php"); exit(); }
    elseif ($_SESSION['user_role'] == 'manager') { header("Location: manager/dashboard.php"); exit(); }
    elseif ($_SESSION['user_role'] == 'employe') { header("Location: employe/dashboard.php"); exit(); }
    elseif ($_SESSION['user_role'] == 'viewer') { header("Location: viewer/dashboard.php"); exit(); }
}

$erreur = '';

if ($_SERVER['REQUEST_METHOD'] == 'POST') {
    $login = $_POST['login'];
    $password = $_POST['password'];

    $users = [
        'admin'  => ['password' => 'password', 'role' => 'admin',   'nom' => 'Admin',      'prenom' => 'Systeme'],
        'rh'     => ['password' => 'password', 'role' => 'manager',  'nom' => 'RH',         'prenom' => 'Manager'],
        'karim'  => ['password' => '123456',   'role' => 'employe',  'nom' => 'Benjelloun', 'prenom' => 'Karim'],
        'viewer' => ['password' => 'viewer123','role' => 'viewer',   'nom' => 'Consultant', 'prenom' => 'Viewer']
    ];

    if (isset($users[$login]) && $users[$login]['password'] == $password) {
        $_SESSION['user_id']     = 1;
        $_SESSION['user_nom']    = $users[$login]['nom'];
        $_SESSION['user_prenom'] = $users[$login]['prenom'];
        $_SESSION['user_role']   = $users[$login]['role'];
        if ($users[$login]['role'] == 'admin')    { header("Location: admin/dashboard.php");   exit(); }
        elseif ($users[$login]['role'] == 'manager')  { header("Location: manager/dashboard.php"); exit(); }
        elseif ($users[$login]['role'] == 'employe')  { header("Location: employe/dashboard.php"); exit(); }
        elseif ($users[$login]['role'] == 'viewer')   { header("Location: viewer/dashboard.php");  exit(); }
    }

    $stmt = $pdo->prepare("SELECT u.*, e.nom, e.prenom FROM utilisateur u JOIN employe e ON u.employe_id = e.id WHERE u.login = ? AND u.statut = 'actif'");
    $stmt->execute([$login]);
    $employe = $stmt->fetch();
    if ($employe && $password == $employe['mot_de_passe']) {
        $_SESSION['user_id']     = $employe['employe_id'];
        $_SESSION['user_nom']    = $employe['nom'];
        $_SESSION['user_prenom'] = $employe['prenom'];
        $_SESSION['user_role']   = 'employe';
        header("Location: employe/dashboard.php"); exit();
    }

    $erreur = 'Identifiant ou mot de passe incorrect';
}
